    const ideasOn = isSession && ideaTicketsOn();
    show('idea-IDEAS', ideasOn && ideaQueue !== 'IDEAS');
    show('idea-SMALL-BUGS', ideasOn && ideaQueue !== 'SMALL-BUGS');
