      if (c && c.codex_cloud === true) return 'other';
      if (_isHermesWorkerRow(c) || _isWatchTowerWorkerRow(c) || _isExternalSpawnRow(c)) return 'workers';
      if (_isHermesMessageRow(c)) return 'messages';
