      const slug = repoPath.replace(/[^A-Za-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
      const number = String(issue.number || '');
      const id = `xrepo-issue-${slug}-${number}`;
      const labels = (issue.labels || []).map(l => (l && l.name) || '').filter(Boolean);
      const title = issue.title || '';
