  // ── Split panel input bar send handler ──
  if ($cpSendBtn && $cpInput) {
    async function sendToSplitTerminal() {
      if (!guardComposerSend($cpInput)) return;
      const text = ($cpInput.value || '').trim();
      const sid = currentSession.id;
      if (!text || !sid) return;
      let announcedFrom = announcedFromForPane(activePaneId());
      if (/^\//.test(text)) announcedFrom = '';
      hideSlashCommandMenu();
      rememberComposerCommand(text);
      $cpSendBtn.disabled = true;
      const flashRed = () => {
        $cpInput.style.borderColor = 'var(--red)';
        setTimeout(() => { $cpInput.style.borderColor = ''; }, 1500);
      };
      const pendingSend = appendPendingSendEcho(announcedInjectionPreview(text, announcedFrom), sid, activePaneId());
      const idempotencyKey = durableActionId('inject');
      const draftConversation = currentConversation;
      const submittedRevision = composerUserEditRevision($cpInput);
      $cpInput.value = '';
      clearInputDraftForConversation(draftConversation);
      $cpInput.style.height = '';
      if ($cpInput.__cpRefresh) $cpInput.__cpRefresh();
      let sendAccepted = false;
      try {
        let res;
        if (currentSession.source === 'pkood') {
          const agentId = currentConversation.replace(/^pkood-/, '');
          res = await fetch('/api/pkood/inject', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({ agent_id: agentId, message: text }),
          });
        } else if (
          currentSession.spawnPid
          && String(sid || '').startsWith('spawning-')
          && currentSession.source !== 'codex'
          && currentSession.source !== 'gemini'
          && currentSession.source !== 'cursor'
          && currentSession.source !== 'antigravity'
          && currentSession.source !== 'kilo'
          && currentSession.source !== 'opencode'
          && currentSession.source !== 'hermes'
        ) {
          // Headless session we spawned — push via stdin pipe
          res = await fetch('/api/sessions/spawned/' + currentSession.spawnPid + '/inject', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({ text, composer_form: 'ccc-composer-v1' }),
          });
        } else {
          const payload = {
            session_id: sid,
            text,
            source: 'composer', composer_form: 'ccc-composer-v1',
            idempotency_key: idempotencyKey,
          };
          if (announcedFrom) payload.announced_from = announcedFrom;
          res = await fetchInjectWithRetry('/api/inject-input', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify(payload),
          });
        }
        let data = {};
        try { data = await res.json(); } catch (_) {}
        sendAccepted = !!(res.ok && data.ok && !data.soft_block && data.submitted !== false);
        if (sendAccepted && data.delivery_id) bindPendingSendDeliveryId(pendingSend, data.delivery_id);
        if (sendAccepted) clearAcceptedComposerInput($cpInput, text, draftConversation, submittedRevision);
        if (res.ok && data.ok && data.submitted === false) {
          removePendingSendEcho(pendingSend);
          showOpToast(data.warning || 'Text typed into Terminal but was not submitted. Press Enter in that terminal tab.', 'error');
        } else if (res.ok && data.ok) {
          if (data.via === 'codex-app-queued') {
            markPendingSendQueued(pendingSend, 'Queued for Codex - will send when the running turn is ready.');
            showOpToast('Queued for Codex.');
            setTimeout(refreshConversationList, 1500);
            setTimeout(refreshConversationList, 3500);
          } else if (data.queued) {
            markPendingSendQueued(pendingSend, 'Queued - will send when the session finishes its current step.');
            showOpToast('Queued - will send when the session finishes its current step.');
          } else if (data.via === 'codex-steer') {
            markPendingSendDelivered(pendingSend, data);
            showOpToast('Sent to running Codex turn.');
            setTimeout(refreshConversationList, 1500);
            setTimeout(refreshConversationList, 3500);
          } else if (data.via === 'codex-app-turn') {
            markPendingSendDelivered(pendingSend, data);
            showOpToast('Codex follow-up started.');
            setTimeout(refreshConversationList, 1500);
            setTimeout(refreshConversationList, 3500);
          } else if (data.via === 'cursor-resume') {
            showOpToast('Cursor follow-up started.');
            setTimeout(refreshConversationList, 1500);
            setTimeout(refreshConversationList, 3500);
          } else if (data.via === 'cursor-resume-queued') {
            showOpToast('Queued until the Cursor follow-up finishes.');
            setTimeout(refreshConversationList, 1500);
            setTimeout(refreshConversationList, 3500);
          } else if (data.via === 'antigravity-resume') {
            showOpToast('Antigravity headless follow-up started.');
            setTimeout(refreshConversationList, 1500);
            setTimeout(refreshConversationList, 3500);
          } else if (data.via === 'antigravity-app') {
            showOpToast('Sent to Antigravity app.');
            setTimeout(refreshConversationList, 1500);
            setTimeout(refreshConversationList, 3500);
          } else if (data.via === 'hermes-resume') {
            markPendingSendDelivered(pendingSend, data);
            showOpToast('Hermes follow-up started.');
            scheduleFireAndWatchRefresh(activePaneId());
          } else if (data.via === 'opencode-resume') {
            markPendingSendDelivered(pendingSend, data);
            showOpToast('OpenCode follow-up started.');
            scheduleFireAndWatchRefresh(activePaneId());
          } else if (data.via === 'wt-send') {
            // Routed through WatchTower (dormant session). Stage the echo
            // copy by transport and track the delivery receipt to landed/lost.
            beginWtReceiptTracking(pendingSend, data, {
              sid, rawText: text, announcedFrom,
              mode: 'send',
              paneId: activePaneId(),
            });
            showOpToast('Accepted by WatchTower' + (data.transport ? ' - ' + data.transport + ' transport.' : '.'));
          }
        } else {
          const reason = formatInjectFailure(data, res.status);
          if (isCursorUsageLimitFailure(data, reason)) {
            appendSendFailureNotice(pendingSend, 'Cursor usage limit hit. Cursor says: ' + reason, activePaneId());
          } else {
            removePendingSendEcho(pendingSend);
          }
          restoreInputAfterSendFailure($cpInput, text);
          flashRed();
          showOpToast('Send failed: ' + reason, 'error', repoNotAllowedToastAction(data));
        }
      } catch (err) {
        if (sendAccepted) {
          console.warn('Accepted message status could not be rendered', err);
          showOpToast('Message accepted. Reload to refresh its status.', 'info');
        } else {
          removePendingSendEcho(pendingSend);
          restoreInputAfterSendFailure($cpInput, text);
          flashRed();
          showOpToast('Send failed: ' + (err.message || 'network error'), 'error');
        }
      }
      if ($cpInput.__cpRefresh) $cpInput.__cpRefresh();
      else $cpSendBtn.disabled = false;
    }
    // Grow the textarea to fit content (capped by CSS max-height, which kicks
    // in scrolling). Runs on every input; cheap enough.
    function cpInputAutoResize() {
      // Empty box: let CSS size the single row. Skipping the scrollHeight
      // read avoids a forced style+layout of the whole dirty document on
      // every session open (restoreInputDraft fires 'input' mid-select).
      if (!$cpInput.value) {
        if ($cpInput.style.height) $cpInput.style.height = '';
        return;
      }
      $cpInput.style.height = '0px';
      $cpInput.style.height = Math.min($cpInput.scrollHeight, 160) + 'px';
    }
    // Enable the send button only when there's text AND we have an active session.
    // Exposed on the element so sendToSplitTerminal can re-run it after clearing value.
    $cpInput.__cpRefresh = function () {
      const hasText = ($cpInput.value || '').trim().length > 0;
      // Antigravity always accepts follow-ups — the server picks
      // CLI-headless / running app / fresh app launch with the prompt
      // prefilled. Don't gate send on antigravityCanSend any more.
      const isAGY = currentSession.source === 'antigravity';
      const agyCanSendNow = !isAGY || antigravityCanSend(currentSession);
      $cpSendBtn.disabled = !hasText || !currentSession.id;
      $cpSendBtn.title = isAGY && !agyCanSendNow
        ? 'Send - runs AGY headless on this session'
        : 'Send';
    };
    $cpSendBtn.addEventListener('click', sendToSplitTerminal);
    $cpInput.addEventListener('input', () => {
      rememberInputDraft($cpInput, currentConversation);
      cpInputAutoResize();
      $cpInput.__cpRefresh();
      refreshSlashCommandMenu($cpInput);
    });
    $cpInput.addEventListener('focus', () => refreshSlashCommandMenu($cpInput));
    $cpInput.addEventListener('click', () => refreshSlashCommandMenu($cpInput));
    $cpInput.addEventListener('keydown', (e) => {
      if (isImeKey(e)) return;
      if (handleSlashCommandKeydown($cpInput, e)) return;
      if (recallLastComposerCommand($cpInput, e)) return;
      // Enter submits, Shift+Enter inserts a newline. Guard against IME
      // composition (Chinese/Japanese input methods dispatch Enter to commit
      // candidate text — we'd otherwise send the prompt mid-composition).
      if (e.key === 'Enter' && !e.shiftKey && !e.isComposing && !isTouchPrimary()) {
        e.preventDefault();
        sendToSplitTerminal();
      }
    });
    // Disabled until the user types.
    $cpInput.__cpRefresh();
  }

  // ── Split panel font controls ──
  const $cpFontMinus = document.getElementById('cpFontMinus');
  const $cpFontPlus = document.getElementById('cpFontPlus');
  if ($cpFontMinus) $cpFontMinus.addEventListener('click', () => {
    convFontScale = Math.max(0.7, +(convFontScale - 0.1).toFixed(1));
    localStorage.setItem('ccc-conv-font-scale', String(convFontScale));
    if ($convPanelView) $convPanelView.style.zoom = convFontScale;
    applyConvFontScale();
  });
  if ($cpFontPlus) $cpFontPlus.addEventListener('click', () => {
    convFontScale = Math.min(1.5, +(convFontScale + 0.1).toFixed(1));
    localStorage.setItem('ccc-conv-font-scale', String(convFontScale));
    if ($convPanelView) $convPanelView.style.zoom = convFontScale;
    applyConvFontScale();
  });
  // Apply initial font scale to split view
  if ($convPanelView) $convPanelView.style.zoom = convFontScale;

  // Auto-refresh archive/session data on a slower cadence. This payload is
  // multi-MB on long-running installs, so the 5s live-status poll owns
  // real-time row activity while this refresh catches structural changes.
  if (!READER_ONLY_POPOUT) {
	  setInterval(async () => {
		    if (_dashboardEventStreamHealthy) return;
		    if (_pollerSkip('sessionsList')) return; if (activeTab !== 'sessions') return;
			    _pollerTick('sessionsList');
		    if (isInlineRenameInProgress()) return;
        if (deferSidebarRenderIfDragging()) return;
		    if (conversationPaneLoading) return;
    // Skip the rerender if the user is actively typing into the
    // composer — innerHTML on the full conv list pauses the main
    // thread long enough to swallow keystrokes. The next 10s tick
    // catches up as soon as the input loses focus or the user pauses.
    const _ae = document.activeElement;
    const _typing = !!(_ae && (_ae.tagName === 'TEXTAREA'
      || (_ae.tagName === 'INPUT' && /^(text|search|email|url|tel|password)$/i.test(_ae.type || 'text'))));
    if (_typing) return;
    // Refresh /api/conversations/all and re-render — cheap because
    // _extract_tail_meta is mtime-cached server-side; only changed
    // JSONLs get re-scanned.
    try {
      await refreshArchiveData();
      if (deferSidebarRenderIfDragging()) return;
      _scheduleSidebarRender();
	    } catch (_) { /* best-effort */ }
	  }, ARCHIVE_REFRESH_INTERVAL_MS);
  }

  // The convToolbar new-session input + Run/pkood toggle were removed —
  // spawning now flows through the sidebar's "+ New session" button (which
  // opens the new-session modal) or the kanban panel's #kptNewSession input.

  // ── In-app update check ─────────────────────────────────────────
  // Hit /api/version/check on page load. If we're behind the latest
  // GitHub release, show the topbar pill. Clicking → modal → POST
  // /api/self-update → show loading overlay → poll /api/version until
  // the new process is up → location.reload().
  const $updPill = document.getElementById('updPill');
  const $updPillText = document.getElementById('updPillText');
  const $updModal = document.getElementById('updModal');
  const $updBackdrop = document.getElementById('updBackdrop');
  const $updVersions = document.getElementById('updVersions');
  const $updCompareLink = document.getElementById('updCompareLink');
  const $updError = document.getElementById('updError');
  const $updLaterBtn = document.getElementById('updLaterBtn');
  const $updNowBtn = document.getElementById('updNowBtn');
  let updCheckData = null;

  // Prominent update experience: the modal opens ITSELF once per new
  // version instead of relying on the user noticing the pill. Suppressed
  // per version via localStorage so a dismissal doesn't nag on every load,
  // and skipped entirely while the First Flight tour owns first-run.
  const UPD_DISMISS_KEY = 'ccc-update-modal-dismissed';
  function updDismissedFor(version) {
    try { return localStorage.getItem(UPD_DISMISS_KEY) === String(version || ''); }
    catch (_) { return true; }
  }
  function updMarkDismissed() {
    if (!updCheckData) return;
    try { localStorage.setItem(UPD_DISMISS_KEY, String(updCheckData.latest || '')); } catch (_) {}
  }
  function updAutoOpen() {
    if (!updCheckData || !updCheckData.behind) return;
    if (updDismissedFor(updCheckData.latest)) return;
    try { if (!localStorage.getItem('ccc-tour-done')) return; } catch (_) {}
    updOpenModal();
  }

  function updRenderPromo() {
    // Show the two newest curated feature promos (WHATS_NEW_FEATURES is
    // newest-first) so the update sells itself; "see all" opens the full
    // What's New modal with mockups.
    const $promo = document.getElementById('updPromo');
    const $list = document.getElementById('updPromoList');
    if (!$promo || !$list || typeof WHATS_NEW_FEATURES === 'undefined') return;
    const features = WHATS_NEW_FEATURES.slice(0, 2);
    if (!features.length) return;
    $list.innerHTML = features.map((f) =>
      '<div class="upd-promo-item">' +
        '<span class="promo-tag">' + f.tag + '</span>' +
        '<span class="promo-title">' + f.title + '</span>' +
        '<span class="promo-date">' + f.date + '</span>' +
      '</div>'
    ).join('');
    $promo.hidden = false;
  }

  function updOpenModal() {
    if (!updCheckData || !updCheckData.behind) return;
    if ($updVersions) {
      $updVersions.innerHTML =
        'Current: <strong>v' + String(updCheckData.current).replace(/[<>&]/g, '') + '</strong> &middot; ' +
        'Latest: <strong>v' + String(updCheckData.latest).replace(/[<>&]/g, '') + '</strong>';
    }
    if ($updCompareLink && updCheckData.changelog_url) {
      $updCompareLink.href = updCheckData.changelog_url;
    }
    updRenderPromo();
    if ($updError) {
      $updError.textContent = '';
      $updError.classList.remove('visible');
    }
    if ($updNowBtn) $updNowBtn.disabled = false;
    if ($updModal) $updModal.classList.add('open');
  }
  function updCloseModal() {
    if ($updModal) $updModal.classList.remove('open');
    updMarkDismissed();
  }
  if ($updPill) $updPill.addEventListener('click', updOpenModal);
  if ($updLaterBtn) $updLaterBtn.addEventListener('click', updCloseModal);
  if ($updBackdrop) $updBackdrop.addEventListener('click', updCloseModal);
  document.addEventListener('keydown', (e) => {
    if (isImeKey(e)) return;
    if (e.key === 'Escape' && $updModal && $updModal.classList.contains('open')) {
      updCloseModal();
    }
  });

  async function updWaitForServer(maxSeconds) {
    // Poll /api/version until the restarted server answers. Returns true on
    // success, false if it never came back within the budget.
    const deadline = Date.now() + maxSeconds * 1000;
    while (Date.now() < deadline) {
      await new Promise(r => setTimeout(r, 1000));
      try {
        const r = await fetch('/api/version', { cache: 'no-store' });
        if (r.ok) return true;
      } catch (_) { /* keep waiting */ }
    }
    return false;
  }

  async function updRunSelfUpdate() {
    if (!$updNowBtn) return;
    $updNowBtn.disabled = true;
    if ($updLaterBtn) $updLaterBtn.disabled = true;
    if ($updError) { $updError.textContent = ''; $updError.classList.remove('visible'); }

    const $overlay = document.getElementById('cccLoadingOverlay');
    const $label = document.getElementById('cccLoadingLabel');
    if ($overlay) {
      $overlay.classList.remove('fade-out', 'gone');
      if ($label) {
        $label.innerHTML =
          '<strong>Updating Command Center&hellip;</strong>' +
          '<div class="ccc-loading-detail">Pulling latest from GitHub and restarting the dashboard and worker.</div>';
      }
    }
    try { sessionStorage.setItem('ccc-updating', '1'); } catch (_) {}

    let data;
    try {
      const r = await fetch('/api/self-update', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      });
      data = await r.json();
    } catch (e) {
      // Socket may drop at the moment execvp fires — treat that as success
      // and start polling for the new process.
      data = { ok: true, _restartRace: true };
    }

    if (!data.ok) {
      // Pre-flight failed (dirty tree, wrong branch, etc). Hide the overlay
      // and surface the reason in the modal so the user can act on it.
      try { sessionStorage.removeItem('ccc-updating'); } catch (_) {}
      if ($overlay) $overlay.classList.add('fade-out', 'gone');
      if ($updError) {
        let msg = data.error || 'Update failed';
        if (data.paths && data.paths.length) {
          msg += '\n\nUncommitted paths:\n  ' + data.paths.slice(0, 8).join('\n  ');
        }
        if ((data.error || '').indexOf('local changes') !== -1) {
          msg += '\n\nCommit or stash the changes in the install directory and try again.';
        } else if ((data.error || '').indexOf('not main') !== -1) {
          msg += '\n\nSwitch the install clone to the main branch and try again.';
        } else if ((data.error || '').indexOf('not a git clone') !== -1) {
          msg += '\n\nSelf-update only works for installs created with `git clone`.';
        }
        $updError.textContent = msg;
        $updError.classList.add('visible');
      }
      showOpToast('Update failed: ' + (data.error || 'unknown'), 'error');
      $updNowBtn.disabled = false;
      if ($updLaterBtn) $updLaterBtn.disabled = false;
      return;
    }

    // Server is restarting. Poll /api/version until it answers, then reload.
    if ($label) {
      $label.innerHTML =
        '<strong>Restarting&hellip;</strong>' +
        '<div class="ccc-loading-detail">Waiting for the new process to bind the port.</div>';
    }
    const ok = await updWaitForServer(30);
    if (ok) {
      // Keep the 'ccc-updating' flag set — the post-reload page reads it to
      // show a transient "Updated" toast, then clears it.
      location.reload();
    } else {
      try { sessionStorage.removeItem('ccc-updating'); } catch (_) {}
      if ($overlay) $overlay.classList.add('fade-out', 'gone');
      showOpToast("Server didn't come back within 30s - try reloading manually", 'error');
      $updNowBtn.disabled = false;
      if ($updLaterBtn) $updLaterBtn.disabled = false;
    }
  }
  if ($updNowBtn) $updNowBtn.addEventListener('click', updRunSelfUpdate);

  const $updPromoMore = document.getElementById('updPromoMore');
  if ($updPromoMore) {
    $updPromoMore.addEventListener('click', () => {
      if ($updModal) $updModal.classList.remove('open');
      whatsNewOpenModal();
    });
  }

  if (!READER_ONLY_POPOUT) {
    (async () => {
      try {
        const r = await fetch('/api/version/check', { cache: 'no-store' });
        const d = await r.json();
        if (d && d.ok && d.behind) {
          updCheckData = d;
          if ($updPillText) {
            $updPillText.textContent = 'Update → v' + String(d.latest).replace(/[<>&]/g, '');
          }
          if ($updPill) $updPill.classList.add('visible');
          // Let the page settle before the modal takes focus.
          setTimeout(updAutoOpen, 1200);
        }
      } catch (_) { /* silent - the pill just stays hidden */ }
    })();
  }

  // ── Sidebar header version + last-updated line ───────────────────
  // Populates #cccVersionLabel ("V4.3") and #cccLastUpdated
  // ("21/05/26-07:38PM") from /api/version. The "check for updates"
  // link forces a fresh /api/version/check (bypassing the 6h server
  // cache) and either opens the existing update modal or toasts that
  // the install is current.
  const $cccVersionLabel = document.getElementById('cccVersionLabel');
  const $cccLastUpdated = document.getElementById('cccLastUpdated');
  const $cccCheckUpdatesLink = document.getElementById('cccCheckUpdatesLink');

  function formatCccUpdatedAt(iso) {
    if (!iso) return '';
    const d = new Date(iso);
    if (isNaN(d.getTime())) return '';
    const pad = (n) => String(n).padStart(2, '0');
    const day = pad(d.getDate());
    const mon = pad(d.getMonth() + 1);
    const yr = pad(d.getFullYear() % 100);
    let h = d.getHours();
    const ampm = h >= 12 ? 'PM' : 'AM';
    h = h % 12; if (h === 0) h = 12;
    const min = pad(d.getMinutes());
    return `${mon}/${day}/${yr}-${pad(h)}:${min}${ampm}`;
  }

  (async () => {
    if (READER_ONLY_POPOUT) return;  // sidebar version label is dashboard chrome
    if (!$cccVersionLabel && !$cccLastUpdated) return;
    try {
      const r = await fetch('/api/version', { cache: 'no-store' });
      const d = await r.json();
      if ($cccVersionLabel && d && d.version) {
        $cccVersionLabel.textContent = 'V' + String(d.version);
        $cccVersionLabel.title = 'Installed version: v' + d.version;
      }
      if ($cccLastUpdated) {
        const formatted = formatCccUpdatedAt(d && d.last_updated);
        $cccLastUpdated.textContent = formatted || '-';
      }
    } catch (_) {
      if ($cccLastUpdated) $cccLastUpdated.textContent = '-';
    }
  })();

  if ($cccCheckUpdatesLink) {
    $cccCheckUpdatesLink.addEventListener('click', async (ev) => {
      ev.preventDefault();
      if ($cccCheckUpdatesLink.classList.contains('checking')) return;
      $cccCheckUpdatesLink.classList.add('checking');
      $cccCheckUpdatesLink.textContent = 'Checking…';
      try {
        const r = await fetch('/api/version/check?force=1', { cache: 'no-store' });
        const d = await r.json();
        if (d && d.ok && d.behind) {
          updCheckData = d;
          if ($updPillText) {
            $updPillText.textContent = 'Update → v' + String(d.latest).replace(/[<>&]/g, '');
          }
          if ($updPill) $updPill.classList.add('visible');
          updOpenModal();
        } else if (d && d.ok) {
          showOpToast('Up to date - v' + (d.current || '?'));
        } else {
          showOpToast('Update check failed: ' + ((d && d.error) || 'unknown'), 'error');
        }
      } catch (e) {
        showOpToast('Update check failed: ' + (e.message || 'network error'), 'error');
      } finally {
        $cccCheckUpdatesLink.classList.remove('checking');
        $cccCheckUpdatesLink.textContent = 'Check for updates';
      }
    });
  }

  // ── System status: SERVER STATUS chip + panel ────────────────
  // One chip in the sidebar header rolls up every service CCC runs; clicking
  // it opens this panel, which is the only place the detail lives. Both read
  // the same _fetchSystemServices() cache, so the chip and the open panel
  // never disagree and never double-fetch.
  //
  // Structural rule: every element below is captured once at boot from
  // index.html. Nothing here rebuilds markup with innerHTML except the queue
  // list inside #cccWtPop, which owns its own children.
  const $sysModal = conversationInitializers.$sysModal();
  const $sysBackdrop = document.getElementById('sysBackdrop');
  const $sysDialog = conversationInitializers.$sysDialog();
  const $sysChip = conversationInitializers.$sysChip();
  const $sysChipVerdict = conversationInitializers.$sysChipVerdict();
  const $sysChipCount = conversationInitializers.$sysChipCount();
  const $sysRollup = conversationInitializers.$sysRollup();
  const $sysRollupText = conversationInitializers.$sysRollupText();
  const $sysLiveRegion = conversationInitializers.$sysLiveRegion();

  // Same confirm string in the panel and in Settings → Maintenance, so the
  // consequence is described identically wherever you click Restart worker.
  const WORKER_RESTART_CONFIRM =
    conversationInitializers.WORKER_RESTART_CONFIRM();
  const WT_RESTART_CONFIRM =
    'Restart the WatchTower server?\n\n'
    + 'In-flight queue workers are stopped mid task and queue draining pauses '
    + 'until it is back. This can take up to 30 seconds.';

  const SYS_ROWS = conversationInitializers.SYS_ROWS();

  let _sysPollTimer = conversationInitializers._sysPollTimer();
  let _sysSpawnedList = conversationInitializers._sysSpawnedList();
  let _sysSpawnedTickTimer = conversationInitializers._sysSpawnedTickTimer();
  let _sysReturnFocus = conversationInitializers._sysReturnFocus();
  let _sysRestartInFlight = conversationInitializers._sysRestartInFlight();
  // Armed but not fired: the dashboard restart counts down for 5s with an
  // Undo before it commits. It locks the same controls as a live restart, but
  // it is NOT "restarting" yet, so it never touches the state pill.
  let _sysArmedRestart = conversationInitializers._sysArmedRestart();
  let _sysFirstAttemptAt = conversationInitializers._sysFirstAttemptAt();
  let _sysLastRollupLevel = conversationInitializers._sysLastRollupLevel();







  // Shared conversation-services.js: sysSetState.
  // ── Time formatting ───────────────────────────────────────────
  // "Started", never "Restarted": CCC cannot tell a first boot from a
  // restart, and guessing wrong in the one panel whose whole job is being
  // trustworthy is not worth the extra word.
  // coarse: drop the minor unit. Used whenever the number is prefixed with
  // "about", because "about 13h 11m ago" claims a precision the word "about"
  // just disclaimed.
  // Shared conversation-services.js: relDuration.

  // Shared conversation-services.js: absStamp.

  // Shared conversation-services.js: formatStarted.



















  // Shared conversation-services.js: _plural.
  // ── Busy lines: what a restart would actually cost, right now ──
  // Shared conversation-services.js: sysDashBusySentence.











  // Shared conversation-services.js: sysWorkerBusySentence.
  // Deliberately carries no queue counts. The Queues panel 12px below states
  // them from a different cache on a different clock, and two numbers for the
  // same thing that disagree by 20 seconds is worse than one number. This line
  // owns the restart implication; the panel owns the counts.






  // Shared conversation-services.js: sysWtBusySentence.
  // ── Rollup ────────────────────────────────────────────────────
  // First match wins, in this exact order. A not-installed WatchTower is
  // excluded entirely: painting the header yellow forever for a feature the
  // user never installed would train them to ignore the chip.
  // Shared conversation-services.js: computeServerRollup.

  // Shared conversation-services.js: _sysCountLabel.

  // Shared conversation-services.js: paintServerChip.

  // Shared conversation-services.js: paintSysRollup.

  // Shared conversation-interactions.js: sysSay.

  // Shared conversation-interactions.js: sysRowSay.

























  const SYS_STATE_PILL = conversationInitializers.SYS_STATE_PILL();
  // Shared conversation-services.js: _sysStateFlag.












  // Shared conversation-services.js: renderSysRow.
  // Why this service's Restart is unavailable, or '' when it is available.
  // Single source of truth: renderSysRow paints from it on every poll AND
  // sysApplyRestartLocks paints from it the instant a restart settles, so the
  // buttons can never sit dead waiting for the next round trip.
  // Shared conversation-interactions.js: sysRestartBlockReason.











  // Shared conversation-interactions.js: sysPaintRestartButton.
  // The ops facts the backend already returns and nothing rendered: pid,
  // version, port, and the crash-loop count. One 11px line.
  // Shared conversation-services.js: sysPaintSvcMeta.











  // Shared conversation-services.js: renderSysAppServerRow.
  // The kap row is read-only: CCC adopts the `kimi web` daemon (or the TUI's
  // embedded server) but never supervises it, so there is no Restart button.
  // Hidden until kap routing is on or a daemon has ever registered — for a
  // setup that has never run kimi web the row is noise.






  // Shared conversation-services.js: renderSysKapRow.
  // ── Spawned processes (System status panel) ──────────────────────
  // Every claude/codex/kimi subprocess CCC has running right now. Prewarm
  // slots carry a kill deadline (expires_at_epoch, server-side TTL is
  // _CLAUDE_PREWARM_TTL_S); everything else has no scheduled kill today.
  // The countdown ticks locally off Date.now() every second
  // (_sysSpawnedTickTimer, started/stopped alongside the modal like
  // _sysPollTimer) so it moves smoothly between the normal 5s data polls
  // instead of jumping once per poll.






  // Shared conversation-services.js: _sysFmtCountdown.
  // spawned_at/started is written server-side via time.strftime('%Y%m%dT%H%M%S')
  // — local time on the machine running CCC, not UTC/epoch.
  // Shared conversation-services.js: _sysParseSpawnedTimestamp.

